#!/bin/bash
# check that the names generated by "btrfs-image -s" are printable

source "$TEST_TOP/common" || exit

check_prereq mkfs.btrfs
check_prereq btrfs
check_prereq btrfs-image

tmp=$(_mktemp_dir image-sanitize-names)
nr_files=200

mkdir "$tmp/src"
for i in $(seq -f '%04g' 1 $nr_files); do
	: > "$tmp/src/name_for_the_garbage_test_$i"
done

truncate -s 128M "$tmp/fs.img"
run_check "$TOP/mkfs.btrfs" -f --rootdir "$tmp/src" "$tmp/fs.img"
run_check "$TOP/btrfs-image" -s "$tmp/fs.img" "$tmp/fs.dump"
run_check "$TOP/btrfs-image" -r "$tmp/fs.dump" "$tmp/restored.img"
run_check_stdout "$TOP/btrfs" inspect-internal dump-tree -t 5 "$tmp/restored.img" > "$tmp/tree.txt"

# The sanitized names are 30 characters long, dump-tree prints a
# non-printable byte as a backslash followed by a letter or three digits
names=$(grep -c 'namelen 30 name: ' "$tmp/tree.txt")
bad=$(sed -n 's/.*namelen 30 name: //p' "$tmp/tree.txt" | sed 's/\\\\//g' | grep -c '\\' || true)

if [ "$names" -lt "$nr_files" ]; then
	_fail "test setup: found only $names sanitized names of $nr_files"
fi
if [ "$bad" -ne 0 ]; then
	_fail "$bad of $names sanitized names contain non-printable characters"
fi

rm -rf -- "$tmp"
